INSERT INTO Benefit VALUES('rewards','Earn 5x points on flights booked directly with airlines or through American Express Travel (up to $500,000 in these purchases per calendar year) and 5x points on prepaid hotels booked through American Express Travel. All other purchases earn 1x points.',NULL,'49d1ce6a-1091-4685-98d2-a04675f9d021','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'5x on flights (direct or Amex Travel, up to $500k/yr) and prepaid Amex Travel hotels; 1x on everything else.','["points","earning","5x flights","5x hotels","amex travel"]','Earning rates','5x travel / 1x other',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','The Platinum Card includes complimentary elite status with several rental car programs: Hertz Gold Plus Rewards President''s Circle, Avis Preferred Plus, and National Emerald Club Executive. These give you faster pick-up (skip the counter), a wider choice of vehicles, and potential upgrades.','Enroll each program once via the Amex benefits portal, then add your membership number to your rental profile. Status is valid while you hold the card.','0e8d9d8c-ed11-48fe-9eb7-f85c92b5c3dc','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'Complimentary elite status with Hertz (President''s Circle), Avis (Preferred Plus), and National (Emerald Club Executive).','["rental car","hertz","avis","national","elite status","upgrade","skip the line"]','Rental car elite status (Hertz, Avis, National)',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Amex provides Car Rental Loss and Damage Insurance when you charge the entire rental to the card and decline the rental company''s collision damage waiver. Within the U.S. it is secondary to your personal auto insurance; outside the U.S. it is primary. Coverage is for damage/theft of the rental vehicle, not liability.','Pay for the rental with the Platinum Card and decline the rental company''s CDW/LDW. Coverage is automatic; file a claim through Amex if damage occurs.','eccbc77b-16fc-429a-8f8d-a8bb3579d083','05dff77f-57d1-4638-a9f4-59e358f54b9d','https://www.americanexpress.com/en-us/benefits/insurance/car-rental-insurance/','Automatic rental car loss and damage coverage when you pay with the card and decline the rental company''s insurance.','["rental car","insurance","collision","damage waiver","primary","secondary"]','Car Rental Loss and Damage Insurance','Secondary in the U.S., primary abroad',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Book through Amex Travel''s Fine Hotels + Resorts or The Hotel Collection to get a $200 annual statement credit on prepaid FHR/The Hotel Collection stays, plus room upgrades when available, daily breakfast for two, and guaranteed 4pm late checkout at FHR properties.','Book a prepaid stay at a Fine Hotels + Resorts or The Hotel Collection property through Amex Travel.','982b578a-d272-4563-8330-8668b04355b9','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'$200 annual credit on prepaid Fine Hotels + Resorts or The Hotel Collection bookings, plus perks like upgrades and late checkout.','["hotel","travel","fine hotels","upgrade","breakfast","credit"]','Fine Hotels + Resorts / Hotel Collection credit','$200/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','$200 in airline fee credits each calendar year for incidental fees (checked bags, seat assignments, in-flight food/drinks) on your selected qualifying airline. Airfare itself does not qualify.','Choose one qualifying airline in your Amex account, then pay incidentals with the card.','63a6b523-1ed3-49f1-a711-e7cf77590a6c','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'$200 annual credit toward incidental airline fees on one selected airline.','["airline","checked bag","incidentals","travel","credit"]','Airline fee credit','$200/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','$15 in Uber Cash each month, plus a $35 bonus in December, for rides and Uber Eats in the U.S. Add the Platinum Card as a payment method in the Uber app to receive it.','Add the card as the payment method in the Uber app; the credit loads automatically each month.','5735fed7-8b18-4c4b-9031-7575cee57c6d','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'$15/month Uber Cash plus a $35 December bonus.','["uber","rideshare","uber eats","credit","monthly"]','Uber Cash','$200/year total',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Access to the Global Lounge Collection, including Centurion Lounges, Priority Pass Select, Delta Sky Club (when flying Delta), and International American Express Lounges. Enrollment may be required for some programs.','Enroll in Priority Pass Select through Amex, then show your card and boarding pass at eligible lounges.','0d83c306-c720-4133-bdf8-93d23ccb238d','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'Global Lounge Collection access, including Centurion Lounges and Priority Pass Select.','["lounge","airport","priority pass","centurion","travel"]','Airport lounge access',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Up to $100 statement credit every 4 years for Global Entry, or up to $85 for TSA PreCheck, when you pay the application fee with the card.',NULL,'02f826ea-6151-400f-9f73-d1a7fd5459a9','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'Statement credit for Global Entry or TSA PreCheck application fees.','["global entry","tsa precheck","security","airport","credit"]','Global Entry / TSA PreCheck credit','Up to $100 every 4 years',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Up to $199 annual statement credit for a CLEAR Plus membership, which lets you verify your identity with your eyes or fingerprint to skip security lines at airports and stadiums.',NULL,'821c168a-a5b7-4091-b339-f8fc645665b3','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'Annual statement credit for a CLEAR Plus membership.','["clear","security","airport","biometric","credit"]','CLEAR Plus credit','Up to $199/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','New purchases are covered against accidental damage or theft for 90 days, up to $10,000 per occurrence and $50,000 per year. A phone bought with the card is covered if it is stolen or damaged soon after purchase.','Pay for the item with the card, then file a claim through Amex within 90 days if it is damaged or stolen.','7a6003e2-40d4-45db-8232-70fc98f39cd2','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'New purchases, including a phone, are covered against theft or damage for 90 days.','["purchase protection","phone","theft","damage","new purchase","shopping","dropped","broken"]','Purchase Protection','Up to $10,000 per claim',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Eligible items get up to one extra year added to the manufacturer''s warranty when the full purchase is made with the card, on warranties of five years or less.',NULL,'86917c07-27bd-4cd8-bd60-cd8c6d228af2','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'Adds up to one extra year to the manufacturer''s warranty on eligible purchases.','["extended warranty","warranty","phone","electronics","repair"]','Extended Warranty','Up to 1 extra year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Pay your monthly cell phone bill with the card and get up to $800 per claim ($1,600 per year, $50 deductible) if your phone is damaged or stolen.','Set the card as the payment method for your monthly wireless bill to activate coverage.','149a84d8-1aa7-4b95-8d36-b3201308fd56','05dff77f-57d1-4638-a9f4-59e358f54b9d',NULL,'Covers a damaged or stolen phone (up to $800 per claim) when you pay your monthly cell bill with the card.','["cell phone protection","phone","cracked screen","theft","cell bill","dropped","broken","damaged"]','Cell Phone Protection','Up to $800 per claim',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 8x points on purchases through Chase Travel (including The Edit) and 4x points on flights and hotels booked directly with the airline or hotel. Earn 3x points on dining worldwide and 1x on all other purchases.',NULL,'fd5c9a21-989b-44a5-bab3-fefc8bf156d2','1b2bbd68-0b21-4b27-b31b-4e3f55785b79',NULL,'8x Chase Travel, 4x direct flights/hotels, 3x dining, 1x other.','["points","earning","8x chase travel","4x flights","3x dining"]','Earning rates','8x Chase Travel',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Auto Rental Collision Damage Waiver is primary coverage (it pays before your personal auto insurance) for damage or theft of a rental vehicle when you charge the rental to the card and decline the rental company''s collision damage waiver. Coverage is up to the actual cash value of the vehicle, generally up to $75,000, and applies in the U.S. and abroad. It does not cover liability.','Charge the full rental to the card and decline the rental company''s CDW/LDW. Coverage is automatic.','ee741609-e6fb-4974-a4d7-462406ff32b5','1b2bbd68-0b21-4b27-b31b-4e3f55785b79','https://www.chase.com/personal/credit-cards/education/benefits/sapphire-reserve-auto-rental-collision-damage-waiver','Primary rental car collision damage waiver up to $75,000 when you pay with the card and decline the rental company''s insurance.','["rental car","insurance","primary","collision","damage waiver","car rental"]','Primary Auto Rental Collision Damage Waiver','Up to $75,000',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Earn a $300 annual statement credit for travel purchases, automatically applied to purchases coded as travel (airfare, hotels, rental cars, transit, etc.).','Automatic — just use the card for travel purchases.','867e1c47-ca3b-412e-aa96-b15a3ea3638b','1b2bbd68-0b21-4b27-b31b-4e3f55785b79',NULL,'$300 annual statement credit that automatically applies to travel purchases.','["travel","credit","airfare","hotel","rental car"]','$300 annual travel credit','$300/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Priority Pass Select membership with access to 1,300+ airport lounges worldwide, plus access to Chase Sapphire Lounges by The Club and select restaurants via the Priority Pass network.','Activate Priority Pass through the Chase benefits portal, then present your Priority Pass card or digital pass.','25b072e7-c349-4400-bc8b-489204ae518e','1b2bbd68-0b21-4b27-b31b-4e3f55785b79',NULL,'Priority Pass Select plus access to Chase Sapphire Lounges.','["lounge","priority pass","airport","travel"]','Airport lounge access',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('insurance','Trip cancellation/interruption coverage up to $10,000 per person and $20,000 per trip when you pay for the trip with the card. Also includes baggage delay, lost luggage, and trip delay reimbursement.',NULL,'6116260f-b892-4ca7-bb69-90580a0431ea','1b2bbd68-0b21-4b27-b31b-4e3f55785b79',NULL,'Trip cancellation/interruption up to $10,000 per person, plus baggage and trip delay coverage.','["trip cancellation","trip delay","baggage","insurance","travel"]','Trip protection','Up to $10,000 per person',NULL,NULL,1789663959,NULL,'seed','verified','seed');
