INSERT INTO Benefit VALUES('security','Up to $100 statement credit every 4 years for Global Entry, or up to $85 for TSA PreCheck, when you pay the application fee with the card.',NULL,'20b51502-01e5-475a-9479-cee514d65d2d','1b2bbd68-0b21-4b27-b31b-4e3f55785b79',NULL,'Global Entry or TSA PreCheck application fee credit.','["global entry","tsa precheck","security","credit"]','Global Entry / TSA PreCheck credit','Up to $100 every 4 years',NULL,NULL,1789663959,NULL,'seed','verified','seed');
