INSERT INTO Benefit VALUES('everyday','Pay your monthly cell phone bill with the card and get up to $800 per claim ($1,000 per year, $50 deductible) if your phone is damaged or stolen.','Set the card as the payment method for your monthly wireless bill to activate coverage.','327f66a0-543b-44c6-93ca-e39665832c45','dee77224-ad3d-4376-8676-9437adefc8fc',NULL,'Covers a damaged or stolen phone (up to $800 per claim) when you pay your monthly cell bill with the card.','["cell phone protection","phone","cracked screen","theft","cell bill","dropped","broken","damaged"]','Cell Phone Protection','Up to $800 per claim',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Use your eyes or fingerprint to verify your identity at CLEAR pods and skip the document-check portion of the security line at 55+ U.S. airports and many stadiums and venues. You still go through the physical screening checkpoint.','Enroll online or at a CLEAR pod, complete identity verification, then use the CLEAR lane at participating airports.','c9fe8ec7-4fda-4bf2-b9b7-93eec5bde6c2','b50a6f83-f2ad-4dcd-9f70-bb7a7eda3ed8',NULL,'Skip the ID-check line at 55+ airports and select venues using biometric verification.','["airport","security","tsa","biometric","skip the line","travel"]','Skip the security line at airports',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
