INSERT INTO Benefit VALUES('shopping','Executive members earn a 2% annual reward on most Costco and Costco.com purchases (some exclusions), paid as a reward certificate. The reward is capped at $1,250 per year.',NULL,'03857475-7b5c-42d1-8a4e-fdef86ae101f','750de1e6-9091-41b2-9bae-78b9a178fe3c',NULL,'2% annual reward on most Costco purchases, up to $1,250/year.','["reward","cash back","shopping","warehouse","annual"]','2% annual reward','Up to $1,250/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Costco Travel offers member-only rental car rates with major agencies (Enterprise, Alamo, National, Budget, Avis, Hertz). Rates often include a free additional driver and there is no booking fee, plus you can stack your credit card''s rental car insurance.','Book through Costco Travel, then pay with a card that offers rental car insurance and decline the rental company''s CDW.','ea3d446f-cfa5-4397-a528-24f3cbe417d2','750de1e6-9091-41b2-9bae-78b9a178fe3c',NULL,'Member-only rental car rates with no booking fees and often a free additional driver.','["rental car","costco travel","car rental","discount","additional driver"]','Costco Travel rental car rates',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Costco Travel packages for hotels, cruises, and vacation rentals often include Costco Shop Cards or extra perks. Executive members also earn the 2% annual reward on eligible travel purchases.',NULL,'d84d9c4b-d3ff-4f1b-9479-a192c679cd77','750de1e6-9091-41b2-9bae-78b9a178fe3c',NULL,'Member pricing and perks on Costco Travel hotel, cruise, and vacation packages.','["travel","hotel","cruise","vacation","costco travel"]','Costco Travel packages',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Discounted gasoline at Costco gas stations (typically among the lowest locally) and Costco''s Concierge tech support and extended warranty on many electronics.',NULL,'fe3c9271-dc8e-4109-9c67-8e6d474906cc','750de1e6-9091-41b2-9bae-78b9a178fe3c',NULL,'Discounted gas plus free tech support and extended warranty on many electronics.','["gas","fuel","electronics","warranty","concierge"]','Gas discounts and Concierge services',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Shop the warehouse and Costco.com with member-only pricing on groceries, electronics, appliances, and more. Gold Star covers the member plus a free household card for one other person at the same address.','Show your membership card (or the Costco app) at the door and at checkout.','5f86175e-65e7-4cc2-9c01-074bc433182e','3f10bb1f-9672-46d5-a903-06dd49ca161d',NULL,'Warehouse and Costco.com access with member-only pricing, plus a free household card.','["warehouse","grocery","member pricing","household card"]','Warehouse access and member pricing',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Costco Travel offers member-only rental car rates with major agencies (Enterprise, Alamo, National, Budget, Avis, Hertz). Rates often include a free additional driver and there is no booking fee, and you can still stack your credit card''s rental car insurance.','Book through Costco Travel, pay with a card that offers rental car insurance, and decline the rental company''s CDW.','f7416c1f-891d-4baa-9995-3cbef2170992','3f10bb1f-9672-46d5-a903-06dd49ca161d',NULL,'Member-only rental car rates with no booking fees and often a free additional driver.','["rental car","costco travel","car rental","discount","additional driver"]','Costco Travel rental car rates',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Discounted gasoline at Costco gas stations, plus member pricing at the pharmacy, optical, and hearing aid centers. Includes Costco Concierge free tech support and extended warranty on many electronics.',NULL,'30a032c6-0aa9-4cb9-a373-2f8ff835cdd8','3f10bb1f-9672-46d5-a903-06dd49ca161d',NULL,'Discounted gas, pharmacy and optical savings, plus free tech support and extended warranty.','["gas","fuel","pharmacy","optical","warranty","concierge"]','Gas, pharmacy, and Concierge services',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Members get discounts at Hertz, Avis, and other rental agencies, often with no additional-driver fee for a spouse or domestic partner and member-only rates. AAA also offers its own ''Show Your Card & Save'' discounts.','Show your AAA card or use the AAA discount code when booking with a participating rental agency.','fae09d5c-6541-46be-bdeb-7ebfc2db7fe1','7d028e3a-b8f7-42c0-a8ae-2d3125cad26e',NULL,'Member discounts at Hertz, Avis, and other rental agencies, often including a free additional driver.','["rental car","discount","hertz","avis","additional driver","aaa"]','Rental car discounts',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('insurance','Roadside assistance including towing, jump-starts, flat tire changes, lockout service, and fuel delivery. Coverage limits and number of service calls depend on your membership tier (Classic, Plus, Premier).','Call the AAA roadside number or use the app when you need help; the responding provider bills AAA directly.','5100dbcd-1458-4d6f-a957-a023080a6072','7d028e3a-b8f7-42c0-a8ae-2d3125cad26e',NULL,'Roadside assistance: towing, jump-starts, tire changes, lockouts, and fuel delivery.','["roadside","towing","jump start","flat tire","lockout","car"]','Roadside assistance',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','AAA members get discounts on hotels, cruises, and attractions, plus access to AAA travel agents and free maps/TripTiks.',NULL,'aca1ffea-e627-4a15-9d60-ce43326d5b36','7d028e3a-b8f7-42c0-a8ae-2d3125cad26e',NULL,'Discounts on hotels, cruises, and attractions, plus trip planning resources.','["hotel","cruise","discount","travel","tripptik"]','Travel discounts and planning',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Plus members get free shipping on most online orders, free curbside pickup, early shopping hours, and 2% Sam''s Cash on qualifying purchases.','Scan your membership at checkout. Sam''s Cash accumulates and can be redeemed in-club or online.','723a5bce-bda3-4676-a07d-72dffc40cb11','e166a556-cc6d-4f7c-82d7-8386fdf40493',NULL,'Free shipping, early shopping hours, and 2% Sam''s Cash on qualifying purchases.','["warehouse","free shipping","cash back","early shopping","sams cash"]','Free shipping and Sam''s Cash','2% Sam''s Cash',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Members save on fuel at Sam''s Club gas stations and get member pricing at the pharmacy and optical centers.',NULL,'8ea17fd4-a2c8-4dd1-9088-eaed4315118d','e166a556-cc6d-4f7c-82d7-8386fdf40493',NULL,'Discounted fuel plus pharmacy and optical member pricing.','["fuel","gas","pharmacy","optical","discount"]','Fuel and pharmacy savings',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Free fast delivery on millions of items, plus access to Prime Video, Prime Music, Prime Reading, and Prime Gaming.','Sign in and look for the Prime badge on eligible items, or open the Prime Video app.','84b4fcd9-8240-4fa5-88a9-80f8caa655da','9603a7e3-20a9-4957-914a-ac4c8a2dcfc1',NULL,'Free fast shipping plus Prime Video, Music, Reading, and Gaming.','["shipping","prime video","prime music","streaming","delivery"]','Free shipping and Prime Video',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
