INSERT INTO Benefit VALUES('shopping','Free delivery on orders over $35, reduced service fees, and 5% back on eligible pickup orders. Benefits can be shared with one family account.','Link the membership to your Instacart account and choose Instacart+ at checkout.','57c325c4-c48e-4c61-9529-2aec5adc8460','4081a4c7-f2b8-4bfc-9620-f2e881c74aab',NULL,'Free delivery over $35 and reduced service fees, shareable with family.','["grocery","delivery","free delivery","pickup","instacart"]','Free grocery delivery',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Redeem points for free nights, and get every fifth consecutive night free on award stays. Members also get member-only rates and free Wi-Fi.','Join for free, then book direct with Marriott and select the member rate.','8f181c3d-18d2-4149-9fe6-57eee98cd488','1c22f68e-4459-4937-ba33-a0180eb13522',NULL,'Fifth night free on award stays, member rates, and free Wi-Fi.','["hotel","free night","fifth night free","points","marriott"]','Fifth night free on award stays',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Points do not expire with account activity, and reward stays of five or more nights get the fifth night free. Members get member discounts, free Wi-Fi, digital check-in, and room selection.','Join for free, book direct, and choose the member rate; use the app for digital check-in.','bbd77acb-de53-449d-9543-4992f4e34be3','1c663856-61a2-4863-a49e-5c9e8f027cf8',NULL,'Fifth night free on reward stays, member discounts, and digital check-in.','["hotel","points","fifth night free","digital check-in","hilton"]','Fifth night free on reward stays',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 5x points on flights and prepaid hotels booked through American Express Travel (up to $500,000 in these purchases per calendar year) and 1.5x points on eligible purchases of $5,000 or more (up to $2 million per year). Other purchases earn 1x points.',NULL,'21cc5fb4-a3c3-4fb6-812d-bb69b4947bea','045139ae-aacb-4cc0-9b46-f5ec0e05b941',NULL,'5x Amex Travel flights and prepaid hotels (up to $500k/yr), 1.5x on large purchases, 1x other.','["points","earning","5x travel","1.5x","business"]','Earning rates','5x Amex Travel',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Up to $200 in annual statement credits for U.S. purchases at Dell Technologies after enrollment, useful for monitors, laptops, and accessories.',NULL,'c80e8227-44ff-4a7e-8cee-5982a9607c6a','045139ae-aacb-4cc0-9b46-f5ec0e05b941',NULL,'$200 annual Dell Technologies credit for business technology purchases.','["dell","technology","credit","business","hardware","laptop","computer","monitor"]','Dell Technologies credit','$200/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Up to $120 in annual credits for Indeed hiring and up to $150 for Adobe Creative Cloud purchases when you enroll and pay with the card.',NULL,'00f3c700-5302-45da-8cf6-cf88a38fe2b6','045139ae-aacb-4cc0-9b46-f5ec0e05b941',NULL,'Annual credits toward Indeed hiring and Adobe Creative Cloud.','["indeed","adobe","hiring","software","credit","business"]','Indeed and Adobe credits','Up to $270/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Get 35% of your points back when you use Pay with Points for eligible flights through Amex Travel, plus access to the Global Lounge Collection.',NULL,'c1ec67aa-760a-4a2e-83a7-38573fa15a81','045139ae-aacb-4cc0-9b46-f5ec0e05b941',NULL,'35% points rebate on eligible flights booked with points, plus lounge access.','["points","flights","amex travel","lounge","business"]','35% points rebate on flights',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Includes InMail credits to message people outside your network, applicant insights to see how you compare to other candidates, and access to LinkedIn Learning courses.',NULL,'0ee094b9-7dc6-45ce-8e8f-9fa696807437','57f9ccb0-3980-417b-b842-ee1e3e1d90a7',NULL,'InMail credits, applicant insights, and LinkedIn Learning access.','["career","inmail","linkedin learning","networking","jobs"]','Networking and learning tools',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','One membership gives access to thousands of gyms, studios, and wellness apps. Many employers subsidize the plan, and you can check in at different locations.',NULL,'80d07355-8d7b-4c7f-8aaf-63d08a7c8608','b1a116f4-56c6-4853-89d5-5f288f27887c',NULL,'Access to a network of gyms, studios, and wellness apps, often employer-subsidized.','["gym","fitness","wellness","wellhub","gympass","employer"]','Gym and wellness network access',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Stores passwords, passkeys, and payment cards in an encrypted vault, monitors for data breaches, and includes Travel Mode to hide sensitive vaults when crossing borders.',NULL,'18e2a293-d347-4f89-a01a-5820744b65cd','54b23a40-0089-4c0d-946a-537d973b27d1',NULL,'Encrypted password vault with breach monitoring and Travel Mode.','["password manager","security","breach","passkeys","travel mode"]','Password manager and breach alerts',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Ad-free listening, offline downloads, and high-quality audio. Premium also includes a monthly audiobook listening allowance, and some plans bundle Hulu.',NULL,'a8a45356-48eb-46c6-8523-8209d461d8db','66b1bc68-dd7f-4c9d-b682-fc52e7ba7851',NULL,'Ad-free music, offline downloads, and audiobook listening hours.','["music","streaming","audiobooks","offline","ad-free"]','Ad-free music and audiobooks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Watch YouTube without ads, play videos in the background or picture-in-picture, download videos for offline viewing, and get YouTube Music Premium included.',NULL,'6777bee9-bd80-423d-9111-4a7bfaee7be9','479e9986-6e86-47cf-87a2-c90dc4bc4fe7',NULL,'Ad-free YouTube, background play, downloads, and YouTube Music.','["youtube","streaming","ad-free","youtube music","downloads"]','Ad-free YouTube and YouTube Music',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 5x points on purchases through Chase Travel; 3x on dining, on gas stations and EV charging, on vacation homes at top brands, and on top streaming services and online grocery (exclusions apply); 2x on all other travel; and 1x on everything else.',NULL,'c0eda287-2ebb-4a89-886b-52782d7ee7d6','a09b67af-134e-4903-8fd8-e7a3cb9e0cbd',NULL,'5x Chase Travel, 3x dining/gas/streaming/online grocery, 2x other travel, 1x other.','["points","earning","5x chase travel","3x dining","2x travel"]','Earning rates','5x Chase Travel',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Primary Auto Rental Coverage when you charge the rental to the card and decline the rental company''s collision insurance. Reimburses theft and collision damage up to $60,000 for most vehicles.','Pay for the rental with the card and decline the rental company''s CDW/LDW.','7dc51073-b908-4c5d-93ca-87a47b224dd6','a09b67af-134e-4903-8fd8-e7a3cb9e0cbd',NULL,'Primary rental car coverage up to $60,000 when you pay with the card and decline the rental company''s insurance.','["rental car","insurance","primary","collision","car rental"]','Primary Auto Rental Coverage','Up to $60,000',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Purchase Protection covers eligible new purchases for 120 days against damage or theft, up to $500 per item.',NULL,'0bd62c07-d77e-4d3f-a657-0aea514e5d2f','a09b67af-134e-4903-8fd8-e7a3cb9e0cbd',NULL,'New purchases are covered against damage or theft for 120 days (up to $500 per item).','["purchase protection","phone","theft","damage","shopping"]','Purchase Protection','Up to $500 per item',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Trip Cancellation and Interruption Insurance reimburses up to $10,000 per covered traveler and $20,000 per trip for prepaid, non-refundable travel if a trip is canceled or cut short. Also includes trip delay and lost luggage coverage.',NULL,'0ecc41e9-0f5d-4101-a78f-8a4844653941','a09b67af-134e-4903-8fd8-e7a3cb9e0cbd',NULL,'Trip cancellation and interruption up to $10,000 per traveler, plus delay and lost luggage coverage.','["trip cancellation","trip delay","luggage","insurance","travel"]','Trip protection','Up to $10,000 per traveler',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Up to $100 in annual statement credits for hotel stays booked through Chase Travel, plus a Global Entry, TSA PreCheck, or NEXUS application fee credit of up to $120 every four years.',NULL,'41f30f49-11c0-4a96-bcc3-cb6b3d6e17cf','a09b67af-134e-4903-8fd8-e7a3cb9e0cbd',NULL,'$100 annual Chase Travel hotel credit and up to $120 for Global Entry/TSA PreCheck.','["hotel credit","global entry","tsa precheck","travel"]','Travel credits','$100/year + $120/4 years',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','Complimentary DashPass membership for DoorDash and Caviar (a $120 value for 12 months) plus a $10 monthly promo on eligible non-restaurant orders.',NULL,'885aea9b-93d8-4524-9d53-13a88828249d','a09b67af-134e-4903-8fd8-e7a3cb9e0cbd',NULL,'Complimentary DoorDash DashPass plus $10/month in DoorDash credits.','["doordash","dashpass","dining","delivery","credit"]','DoorDash DashPass and credits',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 4% cash back on eligible gas and EV charging (first $7,000 per year, then 1%), 3% on restaurants and eligible travel, 2% at Costco and Costco.com, and 1% on all other purchases. No annual fee with a paid Costco membership.','Use the card at Costco and for gas and dining; cash back is paid annually as a reward certificate.','2e46ed90-4f6c-4173-b85d-863fcaffc805','c8923159-5cd0-4ac9-87ce-be4c301c3238',NULL,'4% gas/EV (first $7k/yr), 3% restaurants and travel, 2% Costco, 1% other.','["cash back","earning","4% gas","3% restaurants","3% travel","2% costco","rental car"]','Earning rates','Up to 4% back',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 4x points at restaurants worldwide (up to $50,000 in purchases per calendar year, then 1x) and 4x points at U.S. supermarkets (up to $25,000 per year, then 1x). Earn 3x points on flights booked through American Express Travel and 2x on prepaid car rentals booked through Amex Travel; 1x on everything else.',NULL,'2ef8473a-c5a0-4026-9731-85aaab0da309','c5b32a20-9eeb-4db7-ade3-4489bc7f5df6',NULL,'4x dining (up to $50k/yr) and U.S. supermarkets (up to $25k/yr); 3x Amex Travel flights; 1x other.','["points","earning","4x dining","4x groceries","3x flights"]','Earning rates','4x dining/groceries',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','Up to $120 in annual dining statement credits at participating partners (such as Grubhub, Cheesecake Factory, and select others) and up to $120 in Uber Cash annually ($10/month).',NULL,'14dd0b69-1c1c-44eb-916c-25935c589083','c5b32a20-9eeb-4db7-ade3-4489bc7f5df6',NULL,'$120 annual dining credit plus $120 annual Uber Cash.','["dining credit","uber cash","grubhub","credit","dining"]','Dining and Uber credits','Up to $240/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 5% cash back on travel purchased through Chase Travel, 3% on dining (including takeout and eligible delivery) and drugstores, and an unlimited 1.5% on all other purchases.',NULL,'6e78731a-2298-472f-ae94-e248d66f06c0','87bbad14-475a-4f17-98ff-04c510d377c9',NULL,'5% Chase Travel, 3% dining and drugstores, 1.5% everywhere else.','["cash back","earning","5% chase travel","3% dining","1.5% base"]','Earning rates','1.5% base',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Includes purchase protection and extended warranty on eligible items, plus trip cancellation and interruption insurance on eligible travel.',NULL,'3a21fac8-c343-470c-ab2f-5c34cbf547b0','87bbad14-475a-4f17-98ff-04c510d377c9',NULL,'Purchase protection, extended warranty, and trip insurance on eligible purchases.','["purchase protection","warranty","trip insurance","shopping"]','Purchase and travel protections',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn an unlimited 2% cash back on every purchase: 1% when you buy and an additional 1% as you pay the bill. No annual fee and no categories to track.',NULL,'d5704c08-9751-4496-bea7-440cd08b26ce','c03c931a-48dc-405d-aff3-725ddd6e4b00',NULL,'2% cash back on all purchases (1% when you buy, 1% when you pay).','["cash back","earning","2%","flat rate","everyday"]','Earning rates','2% back',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn up to 4x points at Bilt partner restaurants (20,000+), 3x on hotels booked through Bilt Travel, 2x on flights through Bilt Travel, and 1x on other everyday purchases. Rent and mortgage payments earn up to 1.25x with no transaction fee, with the multiplier based on your everyday card spend.',NULL,'95917888-342d-46f2-bcfb-e0f9e88b550f','a76b0c4c-2270-4ce7-bb1b-23153aa051c0',NULL,'Up to 4x partner dining, 3x Bilt Travel hotels, 2x flights, 1x other, and up to 1.25x on rent (no fee).','["points","earning","rent","dining","travel","no annual fee"]','Earning rates','Up to 1.25x rent',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','$0 delivery fee and reduced service fees on eligible Uber Eats orders over the minimum subtotal, plus up to 10% off eligible delivery and pickup orders.',NULL,'dfa6aa82-7645-44d2-921e-70bb5b75dd49','d0bfe255-ef80-40f2-a9ba-8e364729cb23',NULL,'$0 delivery fees and up to 10% off eligible Uber Eats orders.','["uber eats","delivery","dining","food delivery","delivery fee"]','$0 delivery fee on Uber Eats',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
