INSERT INTO Benefit VALUES('shopping','Access to employee pricing and discounts at 30,000+ national and local merchants across 20+ categories, including electronics, travel, groceries, fitness, and car buying.','Sign in through your employer''s Perks at Work portal and shop via the links to get the discounted price.','46462940-d48e-4767-be8c-e5cecd3a7348','aaa9a934-f998-48db-b26e-bc7d67ca28bf',NULL,'Employee discounts at 30,000+ merchants across electronics, travel, groceries, and more.','["discounts","employee","shopping","electronics","travel"]','Employee discounts',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Earn WOWPoints when you shop through Perks at Work (10x points is like getting 10% back) and access free online classes and coaching through the Community Online Academy.',NULL,'3fe98f80-df7b-4cf8-9417-2eaaaf216184','aaa9a934-f998-48db-b26e-bc7d67ca28bf',NULL,'Earn WOWPoints on purchases plus free online classes and coaching.','["wowpoints","rewards","classes","coaching","wellness"]','WOWPoints and free classes',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Includes Word, Excel, PowerPoint, and Outlook, plus 1 TB of OneDrive cloud storage per person and AI features in supported apps.',NULL,'d4632fc2-0456-4555-8119-6e895c6ca36d','6854e74b-5ecb-4588-a18f-bba73f709e8c',NULL,'Office apps plus 1 TB of OneDrive cloud storage and AI features.','["office","onedrive","storage","productivity","work"]','Office apps and 1 TB storage',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Free shipping with no order minimum on eligible items, free same-day delivery from your store on orders $35+, and free curbside pickup.',NULL,'4866c6b0-821c-4295-a7f4-bbfd4644aa9c','e229d5f5-5aca-443d-a543-2293995fd49e',NULL,'Free shipping with no minimum, plus free same-day delivery on $35+ orders.','["shipping","delivery","grocery","walmart","free delivery"]','Free shipping and delivery',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Save on fuel at Walmart, Murphy, and participating Exxon and Mobil stations, and get Paramount+ Essential included with membership.',NULL,'a0a79505-084d-4651-afba-ec883b554dc2','e229d5f5-5aca-443d-a543-2293995fd49e',NULL,'Fuel discounts plus Paramount+ Essential included.','["fuel","gas","paramount plus","streaming","discount"]','Fuel savings and Paramount+',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Free same-day delivery with Shipt on orders of $35 or more, free 2-day shipping on eligible items, and an extra 30 days for returns.',NULL,'24899faa-37f6-4f7f-9d58-5674347125cb','899bfc2f-f60f-4ebe-a131-2c742b359cbd',NULL,'Free same-day Shipt delivery on $35+, free 2-day shipping, and extended returns.','["target","delivery","shipt","returns","grocery"]','Same-day delivery and extended returns',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','$0 delivery fees and reduced service fees on eligible orders over the minimum subtotal from DashPass merchants, including restaurants, grocery, and convenience.',NULL,'73087952-551c-45b8-b86a-f301a455287e','db45aa66-9b22-49de-8337-6d87ca8cc94e',NULL,'$0 delivery fees and reduced service fees on eligible DashPass orders.','["doordash","delivery","dining","grocery","dashpass"]','$0 delivery fees',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
