INSERT INTO Benefit VALUES('lounge','Access to 1,300+ airport lounges worldwide, plus participating airport restaurants and spas depending on your plan. Many premium credit cards include a Priority Pass membership as a benefit.','Show your digital Priority Pass card and boarding pass at participating lounges.','340ae995-0106-42c3-8f8c-0eb4da8046de','fddd49cc-fc5a-4a6e-89ff-5898526c4ee7',NULL,'Access to 1,300+ airport lounges worldwide, often included with premium cards.','["lounge","airport","priority pass","travel"]','Airport lounge access',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Bundles Apple Music, Apple TV+, and Apple Arcade (plus Apple Fitness+ and more storage on Premier), and includes iCloud+ storage. One bill instead of several.',NULL,'1967c796-81e0-4145-a28b-2b61634a9541','0ac103a0-4a36-4085-a07d-ad7a295a249d',NULL,'Bundles Apple Music, TV+, Arcade, and iCloud+ storage in one subscription.','["apple music","apple tv","icloud","streaming","bundle"]','Apple services bundle',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Encrypted VPN across multiple devices, threat protection that blocks malware and trackers, and a password manager add-on option. Useful on public Wi-Fi while traveling.',NULL,'fd0f6349-9657-4d88-9c61-555cb408b313','cd4f60ba-4df6-425a-9593-2baddd7c2fcd',NULL,'Encrypted VPN with threat protection and multi-device support, handy on public Wi-Fi.','["vpn","security","privacy","travel","public wifi"]','VPN and online protection',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','Shop Sam''s Club warehouses and samsclub.com with member pricing on groceries, electronics, and household goods. Membership includes a free card for one household member.',NULL,'8a35afa2-4dcc-4421-9f78-eaff102d9184','975381a0-df33-42e6-bff3-13c579cc9376',NULL,'Warehouse and online access with member pricing plus a free household card.','["warehouse","grocery","member pricing","household card"]','Warehouse access and member pricing',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Member pricing on fuel at Sam''s Club gas stations, tires and batteries, the pharmacy, and the optical center. Members also get travel and entertainment discounts.',NULL,'50d6ebfd-cd15-4704-912a-7764da55e1ac','975381a0-df33-42e6-bff3-13c579cc9376',NULL,'Fuel, tire, pharmacy, and optical savings plus travel and entertainment discounts.','["fuel","gas","tires","pharmacy","optical","travel"]','Fuel, tire, and pharmacy savings',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('dining','$0 delivery fees on eligible orders over the minimum from Grubhub+ merchants, plus member-only promos and reduced service fees. Often included free with Amazon Prime or other memberships.',NULL,'6ab0953e-a8b0-4dc1-8aa2-20cf619cf61a','abb2b5f9-135f-4f79-a4ef-affd3936cde5',NULL,'$0 delivery fees and member promos on eligible Grubhub orders.','["grubhub","delivery","dining","food delivery","delivery fee"]','$0 delivery fees on eligible orders',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('security','Membership for about five years that lets you use dedicated TSA PreCheck lanes at 200+ airports. You generally keep your shoes, belt, and light jacket on and can leave laptops and liquids in your bag. Often reimbursed by a credit card.',NULL,'39b78607-1ad3-4671-98b5-8279468a1a64','5e7d1761-548d-4df7-a3b3-6a951c6a7f85',NULL,'Faster airport security for about five years, usually with shoes and laptops left in place.','["tsa precheck","airport","security","travel","skip the line"]','Expedited airport security','~5 years',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Five-year membership for expedited U.S. customs and immigration when returning from abroad, using Global Entry kiosks or the mobile app. It includes TSA PreCheck benefits, and many credit cards reimburse the application fee.',NULL,'76c50c12-5eeb-4dea-9b9a-845e31997dc1','4a307a10-1285-4551-a812-8f3020897da0',NULL,'Expedited U.S. customs on return trips for five years, and it includes TSA PreCheck.','["global entry","customs","immigration","tsa precheck","airport","travel"]','Expedited customs and immigration','5 years',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Hilton Honors Gold status includes daily breakfast or a food and beverage credit at many brands, space-available room upgrades, and a bonus on points earned. It also gets the fifth night free on reward stays.',NULL,'26e98cc3-8677-487c-be04-1dd5e2188266','25e4106b-3269-43e9-aafc-69076b90a54c',NULL,'Breakfast or F&B credit, room upgrades, bonus points, and fifth-night-free awards.','["hotel","hilton","status","breakfast","upgrade","fifth night free"]','Hilton Honors Gold perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Hilton Honors Diamond adds lounge access at hotels that have one, stronger upgrade priority, a larger points bonus, and the fifth night free on reward stays.',NULL,'96a866b0-00b2-4f45-bc07-7543f0655ed1','ae35fb66-0c6c-4f18-8ffc-4d450eb86936',NULL,'Lounge access where available, better upgrades, larger points bonus, and fifth-night-free awards.','["hotel","hilton","status","lounge","upgrade"]','Hilton Honors Diamond perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Marriott Bonvoy Gold Elite includes priority late checkout when available, space-available room upgrades, a welcome gift of points, and bonus points on stays.',NULL,'5dcee32d-8ea3-4ad3-be6f-56339024b648','4d246f20-7c71-4dc3-bf1c-21b426a9dd0b',NULL,'Late checkout, room upgrades, and bonus points on stays.','["hotel","marriott","status","late checkout","upgrade"]','Marriott Bonvoy Gold perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Marriott Bonvoy Platinum Elite includes breakfast or a lounge option at many brands, guaranteed 4pm late checkout, stronger upgrades including suites when available, and a bigger points bonus.',NULL,'b0e431b8-5447-4607-aa7f-a7fb80667aa7','6b0d4104-39bd-475b-a8cd-6714738f0f90',NULL,'Breakfast or lounge access, 4pm checkout, stronger upgrades, and bonus points.','["hotel","marriott","status","breakfast","lounge","late checkout"]','Marriott Bonvoy Platinum perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','World of Hyatt Discoverist includes preferred rooms, late checkout when available, complimentary bottled water, and bonus points on eligible stays.',NULL,'5818c250-f083-493a-974c-92609cefaefd','c304d2b1-dcbc-48d5-a849-dc8ba1e42c00',NULL,'Preferred rooms, late checkout, bottled water, and bonus points.','["hotel","hyatt","status","late checkout","points"]','World of Hyatt Discoverist perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','World of Hyatt Globalist is the top tier: suite upgrades when available, free breakfast or lounge access, waived resort fees on award stays, free parking on award stays, and the best points bonus.',NULL,'8f7a9177-2a1d-4c14-bb0b-e585f88123a2','3c81887f-2243-4d44-9e86-8320cd3c731f',NULL,'Suite upgrades, breakfast or lounge access, waived resort fees, and free parking on awards.','["hotel","hyatt","status","suite upgrade","breakfast","lounge"]','World of Hyatt Globalist perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','IHG One Rewards Platinum Elite includes room upgrades when available, bonus points on stays, and priority late checkout.',NULL,'279fc487-d9b7-4762-aa6c-dc1f61aacb9a','efed9003-3ba4-4284-bf8a-e7b8758bd567',NULL,'Room upgrades, bonus points, and late checkout.','["hotel","ihg","status","upgrade","late checkout"]','IHG Platinum Elite perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','IHG One Rewards Diamond Elite adds a breakfast or points option at many brands, stronger upgrade priority, and the highest points bonus.',NULL,'b846da06-1dfb-4bf3-9c23-14282715f642','15abff38-28b5-4a73-bb97-c3b4c81cb2dc',NULL,'Breakfast or points option, stronger upgrades, and top points bonus.','["hotel","ihg","status","breakfast","upgrade"]','IHG Diamond Elite perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Hertz Gold Plus Rewards Five Star and President''s Circle give faster pick-up, a wider choice of vehicles, and space-available upgrades, with the best selection at President''s Circle. Status is often included with premium credit cards or earned through rentals.',NULL,'84f4a79f-d366-4fde-8826-17f73173421b','14bad21d-9a30-4233-902c-75ffe6266ca1',NULL,'Faster pick-up, a wider vehicle choice, and upgrades; often included with premium cards.','["rental car","hertz","elite status","upgrade","skip the line"]','Hertz elite status',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','National Emerald Club Executive lets you choose any car from the Emerald Aisle and pay the midsize rate, with faster pick-up and no counter stop. Often included with premium credit cards.',NULL,'ea027d78-35de-4989-8a12-095fe231e4dc','869f608d-7f24-4b10-aada-359e9c780ca1',NULL,'Choose your own car from the Emerald Aisle and skip the counter; often included with premium cards.','["rental car","national","elite status","emerald aisle","upgrade"]','National Emerald Club Executive',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('car_rental','Avis Preferred Plus and President''s Club offer expedited pick-up, space-available upgrades, and bonus points on rentals. Status is often included with premium credit cards.',NULL,'c014aa38-1d89-480c-ae30-22a4614fa661','afb4eb89-70f7-4c3e-9e45-6b704f2c97e9',NULL,'Expedited pick-up, upgrades, and bonus points; often included with premium cards.','["rental car","avis","elite status","upgrade","skip the line"]','Avis Preferred status',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Annual pass covering entrance fees at more than 2,000 federal recreation sites, including national parks, national forests, and wildlife refuges. It covers the pass holder and passengers in a single vehicle.',NULL,'9a0a2483-85a9-44f6-83f8-f5fb97d2b5ba','33553f09-8f57-475c-a794-5067a0986b75',NULL,'Entrance to 2,000+ national parks and federal recreation sites for a year.','["national parks","entrance fee","outdoors","travel","parks"]','National parks annual pass','$80/year',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn up to 11x total miles on eligible United flights (6x as a United Club member plus 5x from the card), 5x miles on other eligible United purchases, 5x on prepaid hotels through Renowned Hotels & Resorts, 2x on other travel and dining (including delivery), and 1x on everything else.',NULL,'24180489-9b47-48eb-a3bd-b316f1e6a09e','55acce35-0e7e-40fe-9299-881b106692ac',NULL,'Up to 11x on United flights, 5x United purchases/hotels, 2x travel and dining, 1x other.','["miles","earning","united","11x flights","2x dining"]','Earning rates','Up to 11x United',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Includes a United Club membership for access to United Club lounges and participating partner lounges when flying United, plus two free checked bags and Premier Access priority check-in and boarding.',NULL,'60cdb00f-a9dd-4c3a-a211-23613faac38a','55acce35-0e7e-40fe-9299-881b106692ac',NULL,'United Club lounge access, two free checked bags, and Premier Access.','["united","lounge","checked bags","premier access","airline"]','United Club access and bags','2 free checked bags',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 3x miles on Delta purchases made directly with Delta and 1x miles on all other eligible purchases. Also get 20% back on eligible in-flight purchases and 10% back on qualifying concessions purchases (up to $250 per calendar year).',NULL,'56e16a38-bc14-476b-aee4-f37d3c883610','6ddaef02-677b-4497-923f-a198b2dfb437',NULL,'3x miles on Delta purchases, 1x on everything else, plus 20% back in-flight.','["miles","earning","delta","3x delta","inflight"]','Earning rates','3x Delta',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Includes Delta Sky Club access (subject to visit limits for some cardholders) and Centurion Lounge access when flying Delta, plus a companion certificate each year after renewal and status boosts toward Medallion status.',NULL,'36e79f10-c004-4183-b5ea-9549a62dff9c','6ddaef02-677b-4497-923f-a198b2dfb437',NULL,'Sky Club access, an annual companion certificate, and status boosts.','["delta","lounge","companion certificate","status","airline"]','Sky Club access and companion certificate',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 4x miles on eligible American Airlines purchases (5x total after $150,000 in calendar-year spend), 12x miles on eligible AAdvantage Hotels and AAdvantage Cars bookings, and 1x miles on all other purchases.',NULL,'0b2462b7-0932-463f-b23b-a020cd8edfb4','735c6632-31a6-4d4b-b071-f1999d333829',NULL,'4x American Airlines (5x after $150k/yr), 12x AAdvantage Hotels/Cars, 1x other.','["miles","earning","american airlines","4x","12x hotels"]','Earning rates','4x American Airlines',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('lounge','Includes an Admirals Club membership for access to American Airlines Admirals Club lounges, plus a free checked bag and priority boarding on eligible American Airlines flights.',NULL,'07322d61-a90f-49da-8e7d-9a7d915b1a3f','735c6632-31a6-4d4b-b071-f1999d333829',NULL,'Admirals Club membership, a free checked bag, and priority boarding.','["american airlines","admirals club","lounge","checked bag","priority boarding"]','Admirals Club access and bags',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('rewards','Earn 3x miles on Alaska Airlines and Hawaiian Airlines purchases and 2x miles on eligible gas, EV charging, cable, streaming, and local transit (including rideshare), with 1x on all other purchases. Also get 20% back on eligible in-flight purchases.',NULL,'5f6f3cd7-7464-402b-b37d-702da8080323','6e7fbe66-8180-42a0-93de-1c134e82acef',NULL,'3x Alaska/Hawaiian, 2x gas/EV/streaming/transit, 1x other, plus 20% back in-flight.','["miles","earning","alaska airlines","3x","2x gas"]','Earning rates','3x Alaska',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','Includes an annual companion fare from $99 (plus taxes and fees), a free checked bag for you and up to six guests on the same reservation, and priority boarding.',NULL,'9e5253ff-86a2-4457-8897-8c3c7f984c72','6e7fbe66-8180-42a0-93de-1c134e82acef',NULL,'Annual companion fare from $99, a free checked bag, and priority boarding.','["alaska airlines","companion fare","checked bag","priority boarding","airline"]','Companion fare and free checked bag',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Higher-tier T-Mobile plans bundle streaming services (such as Netflix, Apple TV+, or Hulu depending on the plan), include international data and texting, and offer in-flight Wi-Fi on eligible flights.',NULL,'5da78420-8aa1-4492-a577-6ff113e17314','e004eea3-82cd-4046-a102-e78838d8ddf6',NULL,'Bundled streaming, international data, and in-flight Wi-Fi depending on the plan.','["t-mobile","cellular","streaming","netflix","international data","wifi"]','Streaming and international perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','Verizon''s higher-tier plans offer discounted or included bundles (such as Disney+, Hulu, Netflix, or Apple One), plus hotspot data and international perks depending on the plan.',NULL,'e4e10c5e-203d-4195-af05-24ee1b8d3f9c','09136ded-f87c-47da-a7eb-4fb63c62fb50',NULL,'Discounted streaming bundles plus hotspot and international perks depending on the plan.','["verizon","cellular","streaming","disney plus","netflix","hotspot"]','Streaming bundles and hotspot data',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('streaming','AT&T''s higher-tier plans include hotspot data, international roaming perks, and device offers, with some plans bundling streaming services such as Max.',NULL,'22707b8a-d1e6-487f-b3a7-1c46d8e22f59','6aac6cc0-f2fa-4656-8e8e-4d17038e2ddf',NULL,'Hotspot data, international perks, and device/streaming offers depending on the plan.','["att","cellular","streaming","hotspot","international"]','Hotspot and international perks',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Lyra provides evidence-based mental health care through an employer or health plan: therapy, coaching, psychiatry, and medication management, with appointments typically available in days rather than weeks. It also offers self-guided digital programs.',NULL,'c22e6bae-be64-45bb-b21c-d862832984f4','8fdcc43a-c0c3-4950-8475-81319a0b6bb1',NULL,'Therapy, coaching, psychiatry, and medication management with fast appointments, via your employer or health plan.','["mental health","therapy","coaching","psychiatry","eap","employer"]','Therapy, coaching, and psychiatry',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Lyra is designed for the whole family, including children and teens (with thousands of children''s mental health specialists) and couples. Access and cost depend on what your employer or plan has arranged.',NULL,'7a21c60d-f45e-4db2-a657-ca87ee0f09ba','8fdcc43a-c0c3-4950-8475-81319a0b6bb1',NULL,'Whole-family mental health support, including children, teens, and couples.','["family","children","teens","couples","counseling"]','Family and couples support',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Spring Health offers personalized mental health care through employers or insurance: therapy, coaching, medication management, and self-guided tools. A digital assessment matches you to a care plan, and sessions can be as low as $0 depending on your coverage.',NULL,'aa68cbcf-6422-45fe-b4ea-3427784f41e0','d0c15cc2-d554-4977-8452-6566062b8b3d',NULL,'Therapy, coaching, and medication support matched by assessment, sometimes as low as $0 per session.','["mental health","therapy","coaching","medication","eap","employer"]','Personalized therapy and coaching',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Also includes crisis support, specialty programs, and family care, with in-network clinicians you can filter by specialty, language, and availability. Access depends on your employer or health plan.',NULL,'c7b50dfe-db98-4dc8-a649-7aeec2907332','d0c15cc2-d554-4977-8452-6566062b8b3d',NULL,'Crisis support and specialty/family care, depending on your employer or plan.','["crisis support","specialty care","family","employer","insurance"]','Crisis and specialty support',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','One Care.com membership covers child care, senior care, pet care, and housekeeping. You can search local caregivers, view profiles and reviews, and message them in-app. Some employers provide Care.com as a backup-care benefit.',NULL,'327d42e9-b816-4e76-825d-2e967888956e','7f02930c-7ca2-45ca-861a-9d23cac2cbb9',NULL,'One membership to find child, senior, pet, and home caregivers in your area.','["child care","senior care","pet care","housekeeping","caregivers","employer"]','Child, senior, and pet care',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','Premium features include background check requests, detailed caregiver profiles, and the ability to post a job and receive applicants. Employer-sponsored backup care may be free or subsidized.',NULL,'ba869b19-0a71-49c7-9b52-b08073796f1b','7f02930c-7ca2-45ca-861a-9d23cac2cbb9',NULL,'Background checks, caregiver profiles, and job posting; sometimes employer-subsidized.','["background check","backup care","employer","family"]','Screening and backup care',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('travel','AARP membership includes discounts on hotels, car rentals, restaurants, and entertainment, plus access to travel resources and insurance offers. Many discounts are available regardless of age.',NULL,'defdd639-5954-481d-907a-49fe7ee0e5a6','07497902-22d6-45ac-9d11-6a376ba300fa',NULL,'Discounts on hotels, rental cars, dining, and entertainment, plus insurance offers.','["aarp","discount","hotel","rental car","dining","travel"]','Member discounts',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('shopping','REI Co-op membership is a one-time fee that pays an annual member dividend (typically 10% back on eligible full-price purchases), plus access to gear rentals, used gear, shop-service discounts, and member events.',NULL,'950eab69-0284-4769-abb2-e42112df3613','b827a59c-7a1a-46ba-9989-b30d61a40c89',NULL,'One-time membership with an annual dividend, gear rentals, and shop-service discounts.','["rei","outdoors","dividend","gear rental","used gear"]','Member dividend and gear rentals','One-time $30',NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','A free library card often includes free digital access to newspapers like the New York Times, ebooks and audiobooks via Libby, streaming services like Kanopy, research databases, and discounted or free museum passes.',NULL,'1ff5e715-68c9-4967-9232-a86e6cbc0400','a98e0881-394d-46d9-8266-77b49facc4d6',NULL,'Free NYT access, ebooks/audiobooks, streaming, databases, and museum passes.','["library","nytimes","ebooks","libby","kanopy","museum passes"]','Digital access and museum passes',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','A museum membership usually includes free admission for a year, reciprocal admission to other participating museums, previews of new exhibits, member events, and discounts at the shop, cafe, and parking. Benefits vary by museum and tier.',NULL,'d31ad4ab-40e5-4a88-a0c9-df39f996f03f','e69bd1d8-2916-4428-ad1e-cf8c7b22f05f',NULL,'Free year of admission plus reciprocal museum access, previews, events, and shop discounts.','["museum","reciprocal","admission","events","culture"]','Admission and reciprocal access',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
INSERT INTO Benefit VALUES('everyday','A zoo or aquarium membership typically includes a year of free admission, free or discounted parking, guest passes, and discounts on events and food. Many offer reciprocal admission at other zoos and aquariums.',NULL,'504576c8-4091-420a-9531-2cbef923a414','0e8338c5-d21d-4c15-b263-3a82ab05cdc7',NULL,'A year of free admission plus parking, guest passes, and reciprocal zoo access.','["zoo","aquarium","admission","parking","guest passes","family"]','Admission and reciprocal access',NULL,NULL,NULL,1789663959,NULL,'seed','verified','seed');
